style.css:
/* Main page */
body {
    background:
        radial-gradient(circle at 20% 20%, rgba(125, 40, 160, 0.25), transparent 30%),
        radial-gradient(circle at 80% 70%, rgba(180, 30, 50, 0.20), transparent 30%),
        #09090d !important;

    color: #eeeeee !important;
}

/* Main containers / cards */
div,
section,
article {
    border-color: rgba(160, 90, 200, 0.15) !important;
}

/* Headings */
h1, h2, h3, h4 {
    color: #d9a7ff !important;
    text-shadow: 0 0 12px rgba(170, 80, 255, 0.45);
}

/* Links */
a {
    color: #c084fc !important;
    transition: all 0.2s ease !important;
}

a:hover {
    color: #f0abfc !important;
    text-shadow: 0 0 10px rgba(217, 70, 239, 0.8);
}

/* Buttons */
button {
    background: linear-gradient(135deg, #54206f, #8b1e3f) !important;
    color: white !important;
    border: 1px solid #a855f7 !important;
    border-radius: 10px !important;
    transition: all 0.2s ease !important;
}

button:hover {
    box-shadow: 0 0 18px rgba(168, 85, 247, 0.55);
    transform: translateY(-2px);
}

/* Text inputs */
input,
textarea {
    background: #111118 !important;
    color: #eeeeee !important;
    border: 1px solid #54206f !important;
    border-radius: 8px !important;
}

input:focus,
textarea:focus {
    border-color: #a855f7 !important;
    box-shadow: 0 0 12px rgba(168, 85, 247, 0.3) !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #09090d;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(#7e22ce, #991b1b);
    border-radius: 10px;
}

/* Selection */
::selection {
    background: #7e22ce !important;
    color: white !important;
}
